public final class SupplyEventJsonTest {public static void main(String[] args){SupplyEvent e=new SupplyEvent();e.eventType="STOCK_RECEIVED";e.deviceId="WS-1";e.actor="DOM\\alice";e.occurredUtc="2026-08-03T10:00:00Z";e.recordedUtc="2026-08-03T10:00:01Z";e.payload.put("lot","AB\"12");SupplyEvent back=SupplyEventJson.read(SupplyEventJson.write(e));check(e.eventId.equals(back.eventId),"id");check("AB\"12".equals(back.payload("lot")),"payload");SupplyEvent missing=SupplyEventJson.read("{\"schemaVersion\":1,\"eventId\":\"x\",\"eventType\":\"T\",\"occurredUtc\":\"2026-01-01T00:00:00Z\",\"recordedUtc\":\"2026-01-01T00:00:00Z\",\"deviceId\":\"D\",\"sessionId\":\"S\",\"actor\":\"A\"}");check(missing.payload.isEmpty(),"missing payload");System.out.println("SupplyEventJsonTest: PASS");}private static void check(boolean c,String s){if(!c)throw new AssertionError("Failed: "+s);}}
